import React, { useState } from 'react';

const Header = () => {
  const [isClicked, setIsClicked] = useState(false);

  const handleClick = () => {
    setIsClicked(!isClicked);
  };

  const containerClasses = isClicked
    ? 'bg-blue-500 border-blue-600'
    : 'bg-gray-100 border-gray-200 hover:bg-blue-100 hover:border-blue-300';

  const iconClasses = isClicked
    ? 'text-white'
    : 'text-gray-600 group-hover:text-blue-600';

  return (
    <header className="bg-white p-4 flex justify-between items-center h-16 border-b border-gray-200 flex-shrink-0">
      {/* Left Side: Logo and Title */}
      <div className="flex items-center space-x-3">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
        </svg>
        <span className="text-xl font-semibold text-gray-800">Javelin Tracker</span>
      </div>

      {/* Right Side: Wi-Fi Icon */}
      <div
        onClick={handleClick}
        className={`group w-10 h-10 rounded-full flex items-center justify-center border cursor-pointer transition-colors duration-200 ${containerClasses}`}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className={`h-6 w-6 transition-colors duration-200 ${iconClasses}`}
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth={2}
        >
          <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 15a4.125 4.125 0 016.75 0" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M5.25 11.625a8.625 8.625 0 0113.5 0" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M1.875 8.25a13.125 13.125 0 0120.25 0M12 18.75a.75.75 0 100-1.5.75.75 0 000 1.5z" />
        </svg>
      </div>
    </header>
  );
};

export default Header;
